action.command:
python3 -c "
import sys, json, re, os

try:
    data = json.loads(sys.stdin.read() or '{}')
except Exception:
    data = {}
file_path = data.get('filePath') or os.environ.get('KIRO_FILE_PATH', '')

if not file_path.endswith('.md'):
    sys.exit(0)

try:
    with open(file_path, 'r') as f:
        content = f.read()
except Exception:
    sys.exit(0)

if not content.startswith('---'):
    sys.exit(0)

parts = content.split('---', 2)
if len(parts) < 3:
    sys.exit(0)

match = re.search(r'^summary:\s*[\"'](.+?)[\"']', parts[1], re.MULTILINE)
if not match:
    match = re.search(r'^summary:\s*(.+)$', parts[1], re.MULTILINE)

if match:
    summary = match.group(1).strip().strip('\"').strip(\"'\")
    if len(summary) > 120:
        print(f'WARNING: summary is {len(summary)} chars (max 120). File: {file_path}', file=sys.stderr)
        print(f'Summary: \"{summary[:50]}...\"', file=sys.stderr)

sys.exit(0)
"
